6	 * @test @b neon_rot_ldr_at_top_rowmajor
7	 * @parblock
8	 * Microarchitecture-dimension variant of neon_rot_ldr_at_top (2026-09-08).
9	 *
10	 * The 55-record dump campaign showed the corruption concentrated on the
11	 * FIRST indices of the inner loop (idx 0 + idx 1 = 36/55 records) while the
12	 * buffer spans 1024 entries. The parent's inner loop revisits the same
13	 * buffer in the same order every outer iteration: the memory system sees
14	 * the identical touch sequence, and idx 0/1 are the "coldest / most
15	 * forward-progress-dependent" slots of each pass.
16	 * This variant walks the buffer in a REVISED order: even outer iterations
17	 * sweep indices ascending, odd outer iterations sweep descending. The
18	 * touch pattern at idx 0/1 then differs from the parent's (on a descending
19	 * pass, index 0 is the LAST element touched, with a fully-warm pipeline
20	 * behind it, and the store->load adjacency across the loop seam changes).
21	 *   strong idx-0/1 signal also on this variant  -> the signature follows
22	 *      the buffer slots themselves (address-local, e.g. same L1D set/way)
23	 *   signature moves to the sweep seam / disappears              ->
24	 *      it follows the forward-progress position in the sweep
25	 * Same skeleton otherwise: 3rd ldr at top + 2-src loads + rotating ALU
26	 * (add/eor/and/orr) + back-to-back str/str; memcmp in cold path.
27	 * @endparblock
28	 */
29	
30	#include "sandstone.h"
31	#include <cstdint>
32	#include <cstring>
33	
34	#if defined(__aarch64__)
35	#include <arm_neon.h>
36	#endif
37	
38	#define NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT 1024
39	
40	struct NeonRotLdrAtTopRowMajorData {
41	    uint64x2_t *srcA;
42	    uint64x2_t *srcB;
43	    uint64x2_t *scratch;
44	    uint64x2_t *expected;
45	};
46	
47	#if defined(__aarch64__)
48	
49	static inline void store_vec(void *addr, uint64x2_t val) {
50	    vst1q_u64(static_cast<uint64_t *>(addr), val);
51	}
52	
53	static inline uint64x2_t load_vec(const void *addr) {
54	    uint64x2_t res;
55	    __asm__ volatile ("ldr %q0, [%1]" : "=w"(res) : "r"(addr) : "memory");
56	    return res;
57	}
58	
59	#endif
