63	    data->srcA = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT * sizeof(uint64x2_t)));
64	    data->srcB = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT * sizeof(uint64x2_t)));
65	    data->scratch = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT * sizeof(uint64x2_t)));
66	    data->expected = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT * sizeof(uint64x2_t)));
67	
68	    memset_random(data->srcA, NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT * sizeof(uint64x2_t));
69	    memset_random(data->srcB, NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT * sizeof(uint64x2_t));
70	    memset_random(data->scratch, NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT * sizeof(uint64x2_t));
71	
72	    /* golden: same rotating composition, computed on the same NEON units */
73	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_ROWMAJOR_COUNT; i++) {
74	        switch (i % 4) {
75	            case 0: data->expected[i] = vaddq_u64(data->srcA[i], data->srcB[i]); break;
76	            case 1: data->expected[i] = veorq_u64(data->srcA[i], data->srcB[i]); break;
77	            case 2: data->expected[i] = vandq_u64(data->srcA[i], data->srcB[i]); break;
