5	 *
6	 * @test @b movbe
7	 * @parblock
8	 * movbe followed by another movbe which would restore the original byte order.
9	 * Tests byte swapping logic.
10	 * @endparblock
11	 */
12	
13	#include "sandstone.h"
14	
15	#define MOVBE_BUFFER_SIZE (1 << 14)
16	
17	struct movbe_data {
18	    uint32_t *input;
19	    uint32_t *swapped;
20	};
21	
22	static int movbe_init(struct test *test)
23	{
24	    movbe_data *data = (movbe_data *)malloc(sizeof(movbe_data));
25	    data->input = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
26	    data->swapped = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
27	
28	    for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
29	        data->input[i] = random32();
30	    }
31	
32	    test->data = data;
33	    return EXIT_SUCCESS;
34	}
35	
36	static int movbe_run(struct test *test, int cpu)
37	{
38	    movbe_data *data = (movbe_data *)test->data;
39	
40	    TEST_LOOP(test, 1 << 13) {
41	        for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
42	            // Perform "movbe" (Byte Swap)
43	            uint32_t val = data->input[i];
44	            val = __builtin_bswap32(val);
45	            
46	            // Store swapped value
47	            data->swapped[i] = val;
48	
49	            // Perform another "movbe" to restore original order
50	            // This tests the reversibility and correctness of the operation
51	            val = __builtin_bswap32(val);
52	
53	            // Check if we got the original value back
54	            if (val != data->input[i]) {
55	                report_fail_msg("MovBE: Round-trip failed at index %u", i);
56	            }
57	        }
58	    }
59	
60	    return EXIT_SUCCESS;
61	}
62	
63	static int movbe_cleanup(struct test *test)
64	{
65	    movbe_data *data = (movbe_data *)test->data;
66	    if (data) {
67	        free(data->input);
68	        free(data->swapped);
69	        free(data);
70	    }
71	    return EXIT_SUCCESS;
72	}
73	
74	DECLARE_TEST(movbe, "movbe followed by another movbe which would restore the original byte order")
75	    .test_init = movbe_init,
76	    .test_run = movbe_run,
77	    .test_cleanup = movbe_cleanup,
78	    .quality_level = TEST_QUALITY_PROD,
79	END_DECLARE_TEST
