12	 * presence may affect the defect by:
13	 *   - putting the input cache line into a different state (if the compiler
14	 *     ever speculated aliasing), or
15	 *   - occupying the store buffer / LSU so the follow-up reload (the
16	 *     defect-triggering ldr) is delayed/reshuffled.
17	 *
18	 * Compare this variant's trigger rate + XOR pattern against the baseline
19	 * movbe_dump to decide whether the store side-effect is part of the
20	 * trigger mechanism.
21	 * @endparblock
22	 */
23	
24	#include "sandstone.h"
25	
26	#define MOVBE_BUFFER_SIZE (1 << 14)
27	
28	struct movbe_data {
29	    uint32_t *input;
30	    uint32_t *swapped;
31	};
