33	static int movbe_init(struct test *test)
34	{
35	    movbe_data *data = (movbe_data *)malloc(sizeof(movbe_data));
36	    data->input = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
37	    data->swapped = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
38	
39	    for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
40	        data->input[i] = random32();
41	    }
42	
43	    test->data = data;
44	    return EXIT_SUCCESS;
45	}
46	
