50	
51	    TEST_LOOP(test, 1 << 13) {
52	        for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
53	            // PROBE A: no store. Use a volatile read for the comparison so
54	            // the compiler cannot prove val == data->input[i] and delete the
55	            // whole loop body (it would otherwise: with no store there is no
56	            // aliasing excuse, so bswap(bswap(x)) == x folds the compare to
